import { invoke, isTauri } from "@tauri-apps/api/core";
import { listen, type UnlistenFn } from "@tauri-apps/api/event";

import type {
  StructuredIpcError,
  TerminalLifecyclePayload,
  TerminalOutputPayload,
  Worktree,
  WorktreeChangedPayload,
} from "./types";

export function isTauriRuntime() {
  return isTauri();
}

export async function listWorktrees() {
  if (!isTauri()) return [] as Worktree[];
  return invoke<Worktree[]>("cmd_worktree_list");
}

export async function createWorktree(request: { wsId: string; slug: string; baseRef?: string | null }) {
  return invoke<Worktree>("cmd_worktree_create", {
    request: {
      wsId: request.wsId,
      slug: request.slug,
      baseRef: request.baseRef ?? null,
    },
  });
}

export async function spawnTerminal(request: { workspaceId: string; worktreeId: string }) {
  if (!isTauri()) return `preview:${request.workspaceId}:${request.worktreeId}:${crypto.randomUUID()}`;
  return invoke<string>("cmd_terminal_spawn", { request });
}

export async function writeTerminal(request: { sessionId: string; data: string }) {
  if (!isTauri()) return;
  await invoke("cmd_terminal_write", request);
}

export async function resizeTerminal(request: { sessionId: string; cols: number; rows: number }) {
  if (!isTauri()) return;
  await invoke("cmd_terminal_resize", request);
}

export async function closeTerminal(sessionId: string) {
  if (!isTauri()) return;
  await invoke("cmd_terminal_close", { sessionId });
}

export async function onTerminalOutput(handler: (payload: TerminalOutputPayload) => void): Promise<UnlistenFn> {
  if (!isTauri()) return () => undefined;
  return listen<TerminalOutputPayload>("terminal_output", (event) => handler(event.payload));
}

export async function onTerminalLifecycle(handler: (payload: TerminalLifecyclePayload) => void): Promise<UnlistenFn> {
  if (!isTauri()) return () => undefined;
  return listen<TerminalLifecyclePayload>("terminal_lifecycle", (event) => handler(event.payload));
}

export async function onWorktreeChanged(handler: (payload: WorktreeChangedPayload) => void): Promise<UnlistenFn> {
  if (!isTauri()) return () => undefined;
  return listen<WorktreeChangedPayload>("worktree_changed", (event) => handler(event.payload));
}

export function toIpcError(error: unknown): StructuredIpcError {
  if (isStructuredIpcError(error)) return error;
  return {
    code: "UNKNOWN",
    message: error instanceof Error ? error.message : "Unknown IPC error",
    details: {},
  };
}

export function isStructuredIpcError(error: unknown): error is StructuredIpcError {
  if (!error || typeof error !== "object") return false;
  const candidate = error as Partial<StructuredIpcError>;
  return (
    typeof candidate.code === "string" &&
    typeof candidate.message === "string" &&
    !!candidate.details &&
    typeof candidate.details === "object" &&
    !Array.isArray(candidate.details)
  );
}

import { FolderPlus, GitBranch, Plus, X } from "lucide-react";
import { useCallback, useMemo, useState } from "react";

import { Sidebar } from "./components/Sidebar";
import { TabBar } from "./components/TabBar";
import { TerminalSplitView } from "./components/TerminalSplitView";
import { WorkspaceHeader } from "./components/WorkspaceHeader";
import { createWorktree, toIpcError } from "./lib/tauri";
import type { StructuredIpcError, Worktree } from "./lib/types";
import { useWorkspaceRuntime } from "./state/workspaceRuntime";
import { useWorkspaceStore } from "./state/workspaceStore";

export function App() {
  const {
    state,
    agents,
    openTab,
    ensureTabForWorktree,
    closeTab,
    enableSplit,
    rotateSplit,
    disableSplit,
    activatePrimary,
    syncWorktrees,
  } = useWorkspaceStore();
  const { runtimeError, refreshWorktrees, reportRuntimeError } = useWorkspaceRuntime({
    activeWorktreeId: state.activeWorktreeId,
    syncWorktrees,
    ensureTabForWorktree,
  });
  const [isCreateOpen, setIsCreateOpen] = useState(false);
  const [newSlug, setNewSlug] = useState("");
  const [newBaseRef, setNewBaseRef] = useState("HEAD");
  const [createError, setCreateError] = useState<string | null>(null);

  const activeWorktree = useMemo(
    () => state.worktrees.find((worktree) => worktree.worktreeId === state.activeWorktreeId) ?? null,
    [state.activeWorktreeId, state.worktrees],
  );
  const activeAgent = agents.find((agent) => agent.worktreeId === activeWorktree?.worktreeId);

  const handleSelectWorktree = useCallback(
    (worktree: Worktree) => {
      void ensureTabForWorktree(worktree).catch(reportRuntimeError);
    },
    [ensureTabForWorktree, reportRuntimeError],
  );

  const handleCreateWorktreeSubmit = async (event: React.FormEvent) => {
    event.preventDefault();
    const slug = newSlug.trim();
    if (!slug || !activeWorktree) return;

    try {
      setCreateError(null);
      await createWorktree({ wsId: activeWorktree.wsId, slug, baseRef: newBaseRef || null });
      setIsCreateOpen(false);
      setNewSlug("");
      await refreshWorktrees();
    } catch (error) {
      const ipcError = toIpcError(error);
      setCreateError(createWorktreeErrorMessage(ipcError));
    }
  };

  const handleAddTerminalTab = () => {
    if (!activeWorktree) return;
    void openTab(activeWorktree).catch(reportRuntimeError);
  };

  const handleCloseTab = (tabId: string) => {
    void closeTab(tabId).catch(reportRuntimeError);
  };

  const handleSplit = () => {
    if (state.layout.split === "none") {
      void enableSplit("horizontal").catch(reportRuntimeError);
    } else if (state.layout.split === "horizontal") {
      rotateSplit();
    } else {
      disableSplit();
    }
  };

  return (
    <div className="flex h-screen w-screen select-none overflow-hidden bg-background font-sans text-foreground">
      <Sidebar
        worktrees={state.worktrees}
        agents={agents}
        activePath={activeWorktree?.path || ""}
        onSelectWorktree={handleSelectWorktree}
        onCreateWorktree={() => {
          setCreateError(null);
          setIsCreateOpen(true);
        }}
      />

      <main className="flex h-full flex-1 flex-col overflow-hidden bg-card">
        {activeWorktree ? (
          <>
            <WorkspaceHeader
              worktree={activeWorktree}
              agent={activeAgent}
              onSplit={handleSplit}
              splitState={state.layout.split}
            />
            <TabBar
              tabs={state.layout.tabs}
              activeTabId={state.layout.primaryTabId ?? ""}
              onActivate={activatePrimary}
              onClose={handleCloseTab}
              onAdd={handleAddTerminalTab}
            />
            <TerminalSplitView layout={state.layout} sessions={state.sessions} />
          </>
        ) : (
          <div className="flex h-full flex-1 items-center justify-center text-xs text-muted-foreground">
            {runtimeError ? `Workspace unavailable (${runtimeError.code})` : "No workspace available"}
          </div>
        )}
      </main>

      {runtimeError && activeWorktree ? (
        <div className="pointer-events-none fixed bottom-3 right-3 z-40 max-w-error rounded-md border border-destructive/30 bg-card/95 px-3 py-2 text-[11px] text-destructive shadow-lg">
          {runtimeError.code}: {runtimeError.message}
        </div>
      ) : null}

      {isCreateOpen ? (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm">
          <form
            onSubmit={handleCreateWorktreeSubmit}
            className="w-96 animate-enter space-y-4 rounded-xl border border-border bg-card p-5 shadow-2xl"
          >
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2 text-sm font-semibold">
                <FolderPlus className="size-4 text-primary" />
                <span>Create New Worktree</span>
              </div>
              <button
                type="button"
                onClick={() => setIsCreateOpen(false)}
                className="text-muted-foreground hover:text-foreground"
              >
                <X className="size-4" />
              </button>
            </div>

            <div className="space-y-3 text-xs">
              <div>
                <label className="mb-1 block text-muted-foreground">Branch / Worktree Slug</label>
                <input
                  type="text"
                  autoFocus
                  placeholder="e.g. feature-auth"
                  value={newSlug}
                  onChange={(event) => setNewSlug(event.target.value)}
                  className="w-full rounded-md border border-input bg-background px-3 py-1.5 text-xs text-foreground focus:outline-none focus:ring-1 focus:ring-primary"
                />
              </div>

              <div>
                <label className="mb-1 block text-muted-foreground">Base Ref / Branch</label>
                <div className="flex items-center gap-2 rounded-md border border-input bg-background px-3 py-1.5 text-xs text-foreground">
                  <GitBranch className="size-3.5 text-muted-foreground" />
                  <input
                    type="text"
                    value={newBaseRef}
                    onChange={(event) => setNewBaseRef(event.target.value)}
                    className="flex-1 bg-transparent focus:outline-none"
                  />
                </div>
              </div>
              {createError ? <p className="rounded-md bg-destructive/10 px-2 py-1.5 text-destructive">{createError}</p> : null}
            </div>

            <div className="flex justify-end gap-2 pt-2">
              <button
                type="button"
                onClick={() => setIsCreateOpen(false)}
                className="rounded-md px-3 py-1.5 text-xs text-muted-foreground hover:bg-accent hover:text-foreground"
              >
                Cancel
              </button>
              <button
                type="submit"
                className="flex items-center gap-1.5 rounded-md bg-primary px-3.5 py-1.5 text-xs font-medium text-primary-foreground transition-colors hover:bg-primary/90"
              >
                <Plus className="size-3.5" />
                <span>Create Worktree</span>
              </button>
            </div>
          </form>
        </div>
      ) : null}
    </div>
  );
}

function createWorktreeErrorMessage(error: StructuredIpcError) {
  switch (error.code) {
    case "DIRTY_WORKTREE":
      return "The worktree has uncommitted changes. Commit or clean them before this operation.";
    case "WORKTREE_WRITER_BUSY":
      return "The worktree is currently owned by another writer session.";
    case "INVALID_BASE_REF":
      return "The selected base ref is not allowed or does not exist.";
    default:
      return error.message;
  }
}

export default App;

use crate::worktree::model::{CreateWorktreeOptions, DirtyState, Worktree};
use crate::worktree::WorktreeManager;
use serde::{Deserialize, Serialize};
use std::path::PathBuf;
use tauri::State;

#[derive(Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct CreateWorktreeRequest {
    pub repo_root: Option<PathBuf>,
    pub ws_id: String,
    pub slug: String,
    pub path: PathBuf,
    pub base_ref: Option<String>,
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct DeleteWorktreeRequest {
    pub repo_root: Option<PathBuf>,
    pub path: PathBuf,
    pub delete_branch: Option<bool>,
}

#[tauri::command]
pub async fn cmd_worktree_list(
    default_manager: State<'_, WorktreeManager>,
    repo_root: Option<PathBuf>,
) -> Result<Vec<Worktree>, String> {
    let manager = if let Some(root) = repo_root {
        WorktreeManager::new(root)
    } else {
        (*default_manager).clone()
    };

    manager.list_worktrees().map_err(|e| e.to_string())
}

#[tauri::command]
pub async fn cmd_worktree_create(
    default_manager: State<'_, WorktreeManager>,
    request: CreateWorktreeRequest,
) -> Result<Worktree, String> {
    let manager = if let Some(root) = request.repo_root {
        WorktreeManager::new(root)
    } else {
        (*default_manager).clone()
    };

    let mut opts = CreateWorktreeOptions::new(request.ws_id, request.slug, request.path);
    if let Some(base) = request.base_ref {
        opts = opts.with_base_ref(base);
    }

    manager.create_worktree(opts).map_err(|e| e.to_string())
}

#[tauri::command]
pub async fn cmd_worktree_delete(
    default_manager: State<'_, WorktreeManager>,
    request: DeleteWorktreeRequest,
) -> Result<(), String> {
    let manager = if let Some(root) = request.repo_root {
        WorktreeManager::new(root)
    } else {
        (*default_manager).clone()
    };

    let delete_branch = request.delete_branch.unwrap_or(false);
    manager
        .delete_worktree_and_branch(&request.path, delete_branch)
        .map_err(|e| e.to_string())
}

#[tauri::command]
pub async fn cmd_worktree_status(
    default_manager: State<'_, WorktreeManager>,
    path: PathBuf,
) -> Result<DirtyState, String> {
    default_manager.check_dirty(&path).map_err(|e| e.to_string())
}

    fn ensure_no_writer(&self, worktree_path: &Path) -> Result<(), WorktreeError> {
        let canonical = self.canonical_worktree_path(worktree_path)?;
        if let Some(owner_id) = self.writer_leases.owner_canonical(&canonical) {
            return Err(WorktreeError::WriterAlreadyActive {
                path: canonical,
                owner_id,
            });
        }
        Ok(())
    }

    fn remove_worktree_locked(
        &self,
        worktree_path: &Path,
        force: bool,
    ) -> Result<(), WorktreeError> {
        self.ensure_no_writer(worktree_path)?;
        let dirty_state = self.check_dirty(worktree_path)?;
        if dirty_state.is_dirty {
            let count = dirty_state.files.len();
            let files = dirty_state.files.into_iter().map(|f| f.path).collect();
            return Err(WorktreeError::DirtyWorktree {
                path: worktree_path.to_path_buf(),
                count,
                files,
            });
        }

        git_worktree_remove(&self.repo_root, worktree_path, force)?;
        let _ = git_worktree_prune(&self.repo_root);
        Ok(())
    }

    /// Safely removes a worktree while serializing active-writer and dirty checks with removal.
    pub fn remove_worktree(&self, worktree_path: &Path, force: bool) -> Result<(), WorktreeError> {
        let _delete_guard = self.delete_lock.lock();
        self.remove_worktree_locked(worktree_path, force)
    }

    /// Deletes a clean worktree safely (alias for `remove_worktree(path, false)`).
    pub fn safe_delete(&self, worktree_path: &Path) -> Result<(), WorktreeError> {
        self.remove_worktree(worktree_path, false)
    }

    fn branch_is_merged(&self, branch: &str) -> Result<bool, WorktreeError> {
        let merged = run_git(
            &self.repo_root,
            &["branch", "--merged", "HEAD", "--format=%(refname:short)"],
        )?;
        Ok(merged.lines().any(|line| line.trim() == branch))
    }

    pub fn branch_deletion_preview(
        &self,
        worktree_path: &Path,
    ) -> Result<BranchDeletionPreview, WorktreeError> {
        let existing = self
            .find_worktree(worktree_path)?
            .ok_or_else(|| WorktreeError::WorktreeNotFound {
                path: worktree_path.to_path_buf(),
            })?;
        let branch = existing
            .branch_short_name()
            .ok_or_else(|| WorktreeError::ParseError("Detached worktree has no branch".into()))?
            .to_string();
        let head = if existing.head.is_empty() {
            run_git(&self.repo_root, &["rev-parse", "--verify", &branch])?
                .trim()
                .to_string()
        } else {
            existing.head
        };
        let merged = self.branch_is_merged(&branch)?;
        let upstream = run_git(
            &self.repo_root,
            &["rev-parse", "--abbrev-ref", &format!("{branch}@{{upstream}}")],
        )
        .ok()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty());

        let (ahead, behind) = if let Some(upstream_ref) = upstream.as_deref() {
            let counts = run_git(
                &self.repo_root,
                &[
                    "rev-list",
                    "--left-right",
                    "--count",
                    &format!("{upstream_ref}...{branch}"),
                ],
            )?;
            let mut values = counts.split_whitespace();
            let behind = values.next().and_then(|value| value.parse::<u64>().ok());
            let ahead = values.next().and_then(|value| value.parse::<u64>().ok());
            (ahead, behind)
        } else {
            (None, None)
        };

        Ok(BranchDeletionPreview {
            branch,
            head,
            upstream,
            merged,
            ahead,
            behind,
        })
    }

    /// Safely removes a worktree and optionally deletes its branch using `git branch -d`.
    pub fn delete_worktree_and_branch(
        &self,
        worktree_path: &Path,
        delete_branch: bool,
    ) -> Result<(), WorktreeError> {
        let _delete_guard = self.delete_lock.lock();
        self.ensure_no_writer(worktree_path)?;

        let branch_preview = if delete_branch {
            let preview = self.branch_deletion_preview(worktree_path)?;
            if !preview.merged {
                return Err(WorktreeError::UnmergedBranch {
                    branch: preview.branch,
                    head: preview.head,
                });
            }
            Some(preview)
        } else {
            None
        };

        self.remove_worktree_locked(worktree_path, false)?;
        if let Some(preview) = branch_preview {
            git_branch_delete(&self.repo_root, &preview.branch, false)?;
        }
        Ok(())
    }

    /// Explicit destructive branch deletion. Dirty worktrees and active writers remain protected.
    pub fn delete_worktree_and_branch_destructive(
        &self,
        worktree_path: &Path,
        delete_branch: bool,
    ) -> Result<(), WorktreeError> {
        let _delete_guard = self.delete_lock.lock();
        self.ensure_no_writer(worktree_path)?;
        let branch = if delete_branch {
            Some(self.branch_deletion_preview(worktree_path)?.branch)
        } else {
            None
        };

        self.remove_worktree_locked(worktree_path, false)?;
        if let Some(branch) = branch {
            git_branch_delete(&self.repo_root, &branch, true)?;
        }
        Ok(())
    }
}

use orca_lite_lib::terminal::PtyManager;
use orca_lite_lib::worktree::{CreateWorktreeOptions, WorktreeError, WorktreeManager};
use portable_pty::CommandBuilder;
use std::fs;
use std::path::Path;
use std::time::Duration;
use tempfile::TempDir;

fn setup_test_repo() -> (TempDir, WorktreeManager) {
    let temp_dir = TempDir::new().expect("temp dir");
    let repo_path = temp_dir.path();
    orca_lite_lib::worktree::run_git(repo_path, &["init"]).expect("git init");
    orca_lite_lib::worktree::run_git(repo_path, &["config", "user.name", "Orca Test"])
        .expect("git user name");
    orca_lite_lib::worktree::run_git(repo_path, &["config", "user.email", "test@orca.dev"])
        .expect("git user email");
    fs::write(repo_path.join("README.md"), "# base\n").expect("write base");
    orca_lite_lib::worktree::run_git(repo_path, &["add", "README.md"]).expect("git add");
    orca_lite_lib::worktree::run_git(repo_path, &["commit", "-m", "base"]).expect("git commit");
    let manager = WorktreeManager::new(repo_path);
    (temp_dir, manager)
}

fn create_worktree(manager: &WorktreeManager, parent: &Path, slug: &str) -> std::path::PathBuf {
    let path = parent.join(format!("wt-{slug}"));
    manager
        .create_worktree(CreateWorktreeOptions::new("ws-safety", slug, &path))
        .expect("create worktree");
    path
}

#[test]
fn second_writer_is_rejected_and_release_allows_reacquire() {
    let (_repo, manager) = setup_test_repo();
    let wt_parent = TempDir::new().expect("wt parent");
    let wt = create_worktree(&manager, wt_parent.path(), "lease");

    manager.acquire_writer(&wt, "owner-a").expect("first writer");
    assert_eq!(manager.writer_owner(&wt).expect("writer owner"), Some("owner-a".into()));

    let err = manager.acquire_writer(&wt, "owner-b").unwrap_err();
    assert!(matches!(err, WorktreeError::WriterAlreadyActive { .. }));

    manager.release_writer(&wt, "owner-a").expect("release owner-a");
    manager.acquire_writer(&wt, "owner-b").expect("owner-b reacquire");
    assert_eq!(manager.writer_owner(&wt).expect("writer owner"), Some("owner-b".into()));
    manager.release_writer(&wt, "owner-b").expect("release owner-b");
}

#[test]
fn active_writer_blocks_delete() {
    let (_repo, manager) = setup_test_repo();
    let wt_parent = TempDir::new().expect("wt parent");
    let wt = create_worktree(&manager, wt_parent.path(), "active-writer");

    manager.acquire_writer(&wt, "agent-1").expect("writer acquire");
    let err = manager.safe_delete(&wt).unwrap_err();
    assert!(matches!(err, WorktreeError::WriterAlreadyActive { .. }));
    assert!(wt.exists(), "active writer worktree must remain");
    manager.release_writer(&wt, "agent-1").expect("writer release");
}

#[test]
fn default_delete_rejects_clean_unmerged_branch() {
    let (_repo, manager) = setup_test_repo();
    let wt_parent = TempDir::new().expect("wt parent");
    let wt = create_worktree(&manager, wt_parent.path(), "unmerged-default");

    fs::write(wt.join("feature.txt"), "unmerged work\n").expect("write feature");
    orca_lite_lib::worktree::run_git(&wt, &["add", "feature.txt"]).expect("git add");
    orca_lite_lib::worktree::run_git(&wt, &["commit", "-m", "unmerged feature"])
        .expect("feature commit");
    assert!(!manager.is_dirty(&wt).expect("clean status"));

    let err = manager.delete_worktree_and_branch(&wt, true).unwrap_err();
    assert!(matches!(err, WorktreeError::UnmergedBranch { .. }));
    assert!(wt.exists(), "default delete must preserve unmerged worktree");
    let branches = orca_lite_lib::worktree::run_git(manager.repo_root(), &["branch", "--list"])
        .expect("list branches");
    assert!(branches.contains("orca/ws-safety/unmerged-default"));
}

#[test]
fn explicit_destructive_delete_removes_clean_unmerged_branch() {
    let (_repo, manager) = setup_test_repo();
    let wt_parent = TempDir::new().expect("wt parent");
    let wt = create_worktree(&manager, wt_parent.path(), "unmerged-force");

    fs::write(wt.join("feature.txt"), "unmerged work\n").expect("write feature");
    orca_lite_lib::worktree::run_git(&wt, &["add", "feature.txt"]).expect("git add");
    orca_lite_lib::worktree::run_git(&wt, &["commit", "-m", "unmerged feature"])
        .expect("feature commit");

    let preview = manager
        .branch_deletion_preview(&wt)
        .expect("destructive preview");
    assert_eq!(preview.branch, "orca/ws-safety/unmerged-force");
    assert!(!preview.head.is_empty());
    assert!(!preview.merged);

    manager
        .delete_worktree_and_branch_destructive(&wt, true)
        .expect("explicit destructive delete");
    assert!(!wt.exists());
    let branches = orca_lite_lib::worktree::run_git(manager.repo_root(), &["branch", "--list"])
        .expect("list branches");
    assert!(!branches.contains("orca/ws-safety/unmerged-force"));
}

#[tokio::test]
async fn pty_writer_lease_releases_on_close_and_natural_exit() {
    let (_repo, manager) = setup_test_repo();
    let wt_parent = TempDir::new().expect("wt parent");
    let wt = create_worktree(&manager, wt_parent.path(), "pty-lease");
    let pty = PtyManager::new();

    let mut shell = CommandBuilder::new("/bin/sh");
    shell.cwd(&wt);
    let (session_id, _rx) = pty
        .spawn_in_worktree(shell, 80, 24, &manager, &wt)
        .expect("spawn writer terminal");
    assert_eq!(
        manager.writer_owner(&wt).expect("writer owner"),
        Some(session_id.clone())
    );
    pty.close_session(&session_id).await.expect("close terminal");
    assert_eq!(manager.writer_owner(&wt).expect("writer owner"), None);

    let mut one_shot = CommandBuilder::new("/bin/sh");
    one_shot.arg("-c");
    one_shot.arg("exit 0");
    one_shot.cwd(&wt);
    let (natural_id, _rx) = pty
        .spawn_in_worktree(one_shot, 80, 24, &manager, &wt)
        .expect("spawn one-shot terminal");
    assert_eq!(
        manager.writer_owner(&wt).expect("writer owner"),
        Some(natural_id.clone())
    );

    tokio::time::timeout(Duration::from_secs(5), async {
        while pty.has_session(&natural_id) {
            tokio::time::sleep(Duration::from_millis(20)).await;
        }
    })
    .await
    .expect("natural session removal");
    assert_eq!(manager.writer_owner(&wt).expect("writer owner"), None);
}

