   397	        )
   398	        .ok()
   399	        .map(|value| value.trim().to_string())
   400	        .filter(|value| !value.is_empty());
   401	
   402	        let (ahead, behind) = if let Some(upstream_ref) = upstream.as_deref() {
   403	            let counts = run_git(
